const CHARS = "01ABCDEFGHIJKLMNOPQRSTUVWXYZ$#@%&";
function randChar() {
  return CHARS[Math.floor(Math.random() * CHARS.length)];
}

function MatrixRain() {
  const columns = useMemo(
    () =>
      Array.from({ length: 26 }).map((_, i) => ({
        left: (i / 26) * 100 + Math.random() * 2,
        duration: 6 + Math.random() * 8,
        delay: Math.random() * -8,
        chars: Array.from({ length: 18 }).map(() => randChar()),
        hue: Math.random() > 0.5 ? "#2dd4bf" : "#a78bfa",
      })),
    []
  );
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", opacity: 0.35 }}>
      {columns.map((c, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: `${c.left}%`,
            top: 0,
            fontFamily: "ui-monospace, monospace",
            fontSize: 13,
            lineHeight: 1.4,
            color: c.hue,
            animation: `matrixFall ${c.duration}s linear infinite`,
            animationDelay: `${c.delay}s`,
            whiteSpace: "pre",
          }}
        >
          {c.chars.map((ch, j) => (
            <div key={j} style={{ opacity: 1 - j / c.chars.length }}>
              {ch}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

