function TimelineEditForm({ initial, onSubmit, onCancel, submitLabel }) {
  const [date, setDate] = useState(initial?.date || "");
  const [status, setStatus] = useState(initial?.status || "Completed");
  const [title, setTitle] = useState(initial?.title || "");
  const [org, setOrg] = useState(initial?.org || "");
  const [desc, setDesc] = useState(initial?.desc || "");

  const submit = (e) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      date: date.trim() || "—",
      status: status.trim() || "Completed",
      title: title.trim(),
      org: org.trim(),
      desc: desc.trim(),
    });
  };

  const fieldStyle = {
    width: "100%",
    background: "#0a0a0f",
    border: "1px solid rgba(255,255,255,0.1)",
    borderRadius: 10,
    padding: "11px 14px",
    color: "#e5e7eb",
    fontSize: 14,
    marginBottom: 16,
    boxSizing: "border-box",
  };
  const labelStyle = { display: "block", fontSize: 13, color: "#9ca3af", marginBottom: 8 };

  return (
    <form onSubmit={submit}>
      <label style={labelStyle}>Date / Duration</label>
      <input style={fieldStyle} value={date} onChange={(e) => setDate(e.target.value)} placeholder="e.g. Jan — Mar 2026" />

      <label style={labelStyle}>Status</label>
      <input style={fieldStyle} value={status} onChange={(e) => setStatus(e.target.value)} placeholder="e.g. Completed, In progress" />

      <label style={labelStyle}>Title *</label>
      <input style={fieldStyle} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Web Development Intern" />

      <label style={labelStyle}>Organization</label>
      <input style={fieldStyle} value={org} onChange={(e) => setOrg(e.target.value)} placeholder="e.g. Company or College name" />

      <label style={labelStyle}>Description</label>
      <textarea style={{ ...fieldStyle, resize: "vertical" }} rows={4} value={desc} onChange={(e) => setDesc(e.target.value)} placeholder="What did you do?" />

      <div style={{ display: "flex", gap: 10 }}>
        <button type="button" onClick={onCancel} className="outline-btn" style={{ flex: 1, border: "1px solid rgba(255,255,255,0.14)", background: "transparent", padding: "12px", borderRadius: 10, color: "#e5e7eb", fontWeight: 600, fontSize: 14, cursor: "pointer" }}>
          Cancel
        </button>
        <button type="submit" className="grad-btn" style={{ flex: 1, border: "none", padding: "12px", borderRadius: 10, color: "#07080d", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>
          {submitLabel || "Save"}
        </button>
      </div>
    </form>
  );
}

